class Solution {
public:
    bool canFormArray(vector<int>& arr, vector<vector<int>>& pieces) {
        int idx[101];
        for (int i = 0; i < 101; ++i) idx[i] = -1;
        for (int p = 0; p < (int)pieces.size(); ++p) {
            for (int v : pieces[p]) {
                idx[v] = p;
            }
        }
        int i = 0, n = (int)arr.size();
        while (i < n) {
            int p = idx[arr[i]];
            if (p == -1) return false;
            const vector<int>& pc = pieces[p];
            int m = (int)pc.size();
            if (i + m > n) return false;
            for (int j = 0; j < m; ++j) {
                if (arr[i + j] != pc[j]) return false;
            }
            i += m;
        }
        return true;
    }
};
